            elif a.startswith('-'):
                return None, cli_error(f"unexpected argument '{a}' found", usage=True)
            else:
                return None, cli_error(f"unexpected argument '{a}' found", usage=True)
        except CliError as ce:
            return None, cli_error(ce.msg)
        i += 1
    return opts, -1

def run_git(args: List[str], check=False, capture=True, cwd=None):
    if capture:
        p = subprocess.run(['git'] + args, cwd=cwd, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    else:
        p = subprocess.run(['git'] + args, cwd=cwd)
    if check and p.returncode != 0:
        raise RuntimeError((p.stderr or '').strip())
    return p

def git_config(key: str) -> Optional[str]:
    p = run_git(['config', '--get', key])
    if p.returncode == 0:
        return p.stdout.rstrip('\n')
    return None

def parse_bool(v: Optional[str]) -> Optional[bool]:
    if v is None: return None
    s = v.strip().lower()
    if s in ('true','yes','on','1'): return True
    if s in ('false','no','off','0',''): return False
    return None

@dataclass
class DeleteSpec:
    merged_local: bool = False
    merged_remote: Set[str] = field(default_factory=set)
    merged_remote_all: bool = False
    stray: bool = False
    diverged: Set[str] = field(default_factory=set)
    diverged_all: bool = False
    local: bool = False
    remote: Set[str] = field(default_factory=set)
    remote_all: bool = False

def add_remote_spec(target: str, fieldset: Set[str]) -> Tuple[bool, bool]:
    if target == '*':
        return True, False
    fieldset.add(target)
    return False, False

def parse_delete_value(value: str) -> DeleteSpec:
    spec = DeleteSpec()
    parts = value.split(',')
    for item in parts:
        if item == 'merged-local':
            spec.merged_local = True
        elif item == 'stray':
            spec.stray = True
        elif item == 'local':
            spec.local = True
        elif item.startswith('merged:'):
            rem = item[len('merged:'):]
            if rem == '': raise ValueError(f"Invalid delete range format `{item}`")
            spec.merged_local = True
            if rem == '*': spec.merged_remote_all = True
            else: spec.merged_remote.add(rem)
        elif item.startswith('merged-remote:'):
            rem = item[len('merged-remote:'):]
            if rem == '': raise ValueError(f"Invalid delete range format `{item}`")
            if rem == '*': spec.merged_remote_all = True
            else: spec.merged_remote.add(rem)
        elif item.startswith('diverged:'):
            rem = item[len('diverged:'):]
            if rem == '': raise ValueError(f"Invalid delete range format `{item}`")
            if rem == '*': spec.diverged_all = True
            else: spec.diverged.add(rem)
        elif item.startswith('remote:'):
            rem = item[len('remote:'):]
            if rem == '': raise ValueError(f"Invalid delete range format `{item}`")
            if rem == '*': spec.remote_all = True
            else: spec.remote.add(rem)
        else:
            raise ValueError(f"Invalid delete range format `{item}`")
    return spec

def remote_match(remote: str, s: Set[str], allflag: bool) -> bool:
    return allflag or remote in s

@dataclass
class LocalBranch:
    name: str
    oid: str
    upstream: str
    track: str
    subject: str

@dataclass
class RemoteBranch:
    full: str
    remote: str
    branch: str
    oid: str
    subject: str

@dataclass
class LocalDel:
    name: str
    kind: str  # merged or stray
    nontracking: bool = False
    oid: str = ''
    subject: str = ''

@dataclass
class RemoteDel:
    remote: str
    branch: str
    kind: str  # merged or diverged
    nonupstream: bool = False


def split_csv(v: Optional[str]) -> List[str]:
    if not v: return []
    return [x for x in v.split(',') if x != '']

def collect_branches() -> Tuple[Dict[str,LocalBranch], Dict[str,RemoteBranch], Optional[str]]:
    locals: Dict[str, LocalBranch] = {}
    p = run_git(['for-each-ref', '--format=%(refname:short)%00%(objectname)%00%(upstream:short)%00%(upstream:track)%00%(subject)', 'refs/heads'])
    if p.returncode == 0:
        for line in p.stdout.splitlines():
            parts = line.split('\x00')
            if len(parts) >= 5:
                name, oid, upstream, track, subject = parts[0], parts[1], parts[2], parts[3], parts[4]
                locals[name] = LocalBranch(name, oid, upstream, track, subject)
    remotes: Dict[str, RemoteBranch] = {}
    p = run_git(['for-each-ref', '--format=%(refname:short)%00%(objectname)%00%(subject)', 'refs/remotes'])
    if p.returncode == 0:
        for line in p.stdout.splitlines():
            parts = line.split('\x00')
            if len(parts) >= 3:
                full, oid, subject = parts[0], parts[1], parts[2]
                if full.endswith('/HEAD'):
                    continue
                if '/' not in full:
                    continue
                remote, branch = full.split('/',1)
                remotes[full] = RemoteBranch(full, remote, branch, oid, subject)
    p = run_git(['symbolic-ref', '--short', '-q', 'HEAD'])
    current = p.stdout.strip() if p.returncode == 0 and p.stdout.strip() else None
    return locals, remotes, current

def is_ancestor(a: str, b: str) -> bool:
    if not a or not b: return False
    p = run_git(['merge-base', '--is-ancestor', a, b])
    return p.returncode == 0

def any_ancestor(a: str, bases: List[str]) -> bool:
    return any(is_ancestor(a, b) for b in bases)

def protected_local(name: str, patterns: List[str]) -> Optional[str]:
    candidates = [name, f"refs/heads/{name}"]
    for pat in patterns:
        for c in candidates:
            if fnmatch.fnmatchcase(c, pat):
                return pat
    return None

def protected_remote(full: str, patterns: List[str]) -> Optional[str]:
    for pat in patterns:
        if fnmatch.fnmatchcase(full, pat):
            return pat
    return None

def default_base_names(remotes: List[str], locals: Dict[str,LocalBranch]) -> List[str]:
    names = []
    heads = []
    for r in remotes:
        p = run_git(['symbolic-ref', '-q', f'refs/remotes/{r}/HEAD'])
        if p.returncode == 0:
            ref = p.stdout.strip()
            pref = 'refs/remotes/'
            if ref.startswith(pref):
                heads.append(ref[len(pref):])
    for lb in locals.values():
        if lb.upstream in heads:
            names.append(lb.name)
    return sorted(names)

def short_oid(oid: str) -> str:
    p = run_git(['rev-parse', '--short', oid])
    return p.stdout.strip() if p.returncode == 0 else oid[:7]

def apply_config(opts: Options) -> Tuple[Options, Optional[str]]:
    # CLI values override config values.  Boolean no-* flags are the negation of positive config keys.
    if opts.bases is None:
        opts.bases = git_config('trim.bases')
    if opts.protected is None:
        opts.protected = git_config('trim.protected')
    if opts.delete is None:
        opts.delete = git_config('trim.delete')
    if opts.update_interval is None:
        u = git_config('trim.updateInterval')
        if u is not None:
            if not u.isdigit():
                # treat like a runtime error, as config parsing does
                return opts, 'invalid digit found in string'
            opts.update_interval = int(u)
    if not opts.no_update:
        b = parse_bool(git_config('trim.update'))
        if b is False:
            opts.no_update = True
    if not opts.no_confirm:
        b = parse_bool(git_config('trim.confirm'))
        if b is False:
            opts.no_confirm = True
    if not opts.no_detach:
        b = parse_bool(git_config('trim.detach'))
        if b is False:
            opts.no_detach = True
    return opts, None

def render_and_act(opts: Options, spec: DeleteSpec, patterns: List[str], bases_arg: Optional[str]) -> int:
    remp = run_git(['remote'])
    if remp.returncode != 0:
        eprint('Error: git-trim requires at least one remote')
        return 1
    remote_names = [r for r in remp.stdout.splitlines() if r]
    if not remote_names:
        eprint('Error: git-trim requires at least one remote')
        return 1

    update_enabled = not opts.no_update
    if update_enabled:
        # A straightforward public-interface update.  The original leaves a blank line before the report.
        subprocess.run(['git','fetch','--all','--prune'], text=True)
        print()

    locals, remotes, current = collect_branches()
    if bases_arg is not None:
        base_names = sorted(split_csv(bases_arg))
    else:
        base_names = default_base_names(remote_names, locals)
    base_locals = {n for n in base_names if n in locals and locals[n].upstream and locals[n].upstream in remotes}
    base_remote_full = {locals[n].upstream for n in base_locals}
    base_hashes = [remotes[u].oid for u in sorted(base_remote_full) if u in remotes]

    upstream_to_locals: Dict[str, List[str]] = {}
    for lb in locals.values():
        if lb.upstream:
            upstream_to_locals.setdefault(lb.upstream, []).append(lb.name)

    scan_tracking = spec.merged_local or spec.merged_remote_all or bool(spec.merged_remote) or spec.stray or spec.diverged_all or bool(spec.diverged)

    local_remain: Dict[str,str] = {}
    remote_remain: Dict[str,str] = {}
    local_deletes: List[LocalDel] = []
    stray_deletes: List[LocalDel] = []
    remote_deletes: List[RemoteDel] = []
    diverged_remote_delete_keys: Set[str] = set()
    skip_used: Set[int] = set()

    local_state: Dict[str, Dict[str, object]] = {}

    def add_local_delete(lb: LocalBranch, kind: str, nontracking=False):
        d = LocalDel(lb.name, kind, nontracking, lb.oid, lb.subject)
        if kind == 'stray': stray_deletes.append(d)
        else: local_deletes.append(d)

    for name in sorted(locals):
        lb = locals[name]
        ann = ''
        prot = protected_local(name, patterns)
        is_current = (current == name)
        if lb.upstream:
            if not scan_tracking:
                ann = ' *1'; skip_used.add(1)
            elif name in base_locals:
                ann = ' [base]'
            elif lb.upstream not in remotes:
                if spec.stray:
                    if prot:
                        ann = f" [stray, but: protected by a pattern `{prot}`]"
                    elif is_current and opts.no_detach:
                        ann = " [stray, but: HEAD]"
                    else:
                        add_local_delete(lb, 'stray')
                        ann = None
                else:
                    ann = " [stray, but: delete range `stray` was not given]"
                local_state[name] = {'class':'stray'}
            else:
                rb = remotes[lb.upstream]
                lm = any_ancestor(lb.oid, base_hashes)
                rm = any_ancestor(rb.oid, base_hashes)
                local_state[name] = {'class':'normal', 'local_merged': lm, 'remote_merged': rm, 'remote': rb.remote, 'upstream': lb.upstream}
                if lm and not rm:
                    # A merged local branch whose upstream advanced/diverged is treated specially.
                    if remote_match(rb.remote, spec.diverged, spec.diverged_all):
                        if prot:
                            ann = f" [diverged, but: protected by a pattern `{prot}`]"
                        elif is_current and opts.no_detach:
                            ann = " [diverged, but: HEAD]"
                        else:
                            add_local_delete(lb, 'merged')
                            remote_deletes.append(RemoteDel(rb.remote, rb.branch, 'diverged'))
                            diverged_remote_delete_keys.add(rb.full)
                            ann = None
                    else:
                        ann = f" [diverged with refs/remotes/{lb.upstream}, but: delete range `diverged:{rb.remote}` was not given]"
                elif lm:
                    if spec.merged_local:
                        if prot:
                            ann = f" [merged, but: protected by a pattern `{prot}`]"
                        elif is_current and opts.no_detach:
                            ann = " [merged, but: HEAD]"
                        else:
                            add_local_delete(lb, 'merged')
                            ann = None
                    else:
                        ann = " [merged, but: delete range `merged-local` was not given]"
                else:
                    ann = ''
        else:
            lm = any_ancestor(lb.oid, base_hashes)
            if spec.local and lm:
                if prot:
                    ann = f" [merged, but: protected by a pattern `{prot}`]"
                elif is_current and opts.no_detach:
                    ann = " [merged, but: HEAD]"
                else:
                    add_local_delete(lb, 'merged', nontracking=True)
                    ann = None
            elif not spec.local:
                ann = ' *2'; skip_used.add(2)
            else:
                ann = ''
        if ann is not None:
            local_remain[name] = ann

    # Remote refs: annotations/deletes.
    added_remote_delete_keys = {f"{d.remote}/{d.branch}" for d in remote_deletes}
    for full in sorted(remotes):
        rb = remotes[full]
        ann = ''
        prot = protected_remote(full, patterns)
        is_upstream = full in upstream_to_locals
        if is_upstream:
            if not scan_tracking:
                ann = ' *1'; skip_used.add(1)
            elif full in base_remote_full:
                ann = ' [base]'
            else:
                # Classify using the first tracking local branch (stable alphabetical).
                paired_name = sorted(upstream_to_locals[full])[0]
                lb = locals.get(paired_name)
                lm = any_ancestor(lb.oid, base_hashes) if lb else False
                rm = any_ancestor(rb.oid, base_hashes)
                if full in diverged_remote_delete_keys:
                    ann = None
                elif lm and not rm:
                    if remote_match(rb.remote, spec.diverged, spec.diverged_all):
                        if prot:
                            ann = f" [diverged, but: protected by a pattern `{prot}`]"
                        else:
                            # Local protection may have prevented adding the remote; add it unless remote protected.
                            remote_deletes.append(RemoteDel(rb.remote, rb.branch, 'diverged'))
                            diverged_remote_delete_keys.add(full)
                            ann = None
                    else:
                        ann = f" [diverged with refs/heads/{paired_name}, but: delete range `diverged:{rb.remote}` was not given]"
                elif rm:
                    if remote_match(rb.remote, spec.merged_remote, spec.merged_remote_all):
                        if prot:
                            ann = f" [merged, but: protected by a pattern `{prot}`]"
                        else:
                            remote_deletes.append(RemoteDel(rb.remote, rb.branch, 'merged'))
                            ann = None
                    else:
                        ann = f" [merged, but: delete range `merged-remote:{rb.remote}` was not given]"
                else:
                    ann = ''
        else:
            rm = any_ancestor(rb.oid, base_hashes)
            if remote_match(rb.remote, spec.remote, spec.remote_all) and rm:
                if prot:
                    ann = f" [merged, but: protected by a pattern `{prot}`]"
                else:
                    remote_deletes.append(RemoteDel(rb.remote, rb.branch, 'merged', nonupstream=True))
                    ann = None
            elif not remote_match(rb.remote, spec.remote, spec.remote_all):
                if scan_tracking:
                    ann = ' *3'; skip_used.add(3)
                else:
                    ann = ''
            else:
                ann = ''
        if ann is not None:
            remote_remain[full] = ann

    # Deduplicate remote deletes, preserving first occurrence.
    seen = set(); rds=[]
    for d in remote_deletes:
        key = (d.remote,d.branch,d.kind,d.nonupstream)
        key2 = (d.remote,d.branch)
        if key2 in seen: continue
        seen.add(key2); rds.append(d)
    remote_deletes = rds

    print("Branches that will remain:")
    print("  local branches:")
    for name in sorted(local_remain):
        print(f"    {name}{local_remain[name]}")
    print("  remote references:")
    for full in sorted(remote_remain):
        print(f"    {full}{remote_remain[full]}")
    if skip_used:
        print("  Some branches are skipped. Consider following to scan them:")
        if 1 in skip_used:
            print("    *1: Add `--delete 'merged:*'` flag.")
        if 2 in skip_used:
            print("    *2: Set an upstream to make it a tracking branch or add `--delete 'local'` flag.")
        if 3 in skip_used:
            print("    *3: Make it upstream of a tracking branch or add `--delete 'remote:*'` flag.")
    print()

    if local_deletes:
        print("Delete merged local branches:")
        for d in sorted(local_deletes, key=lambda x:x.name):
            suffix = " (non-tracking)" if d.nontracking else ""
            print(f"  - {d.name}{suffix}")
    merged_rds = [d for d in remote_deletes if d.kind == 'merged']
    div_rds = [d for d in remote_deletes if d.kind == 'diverged']
    if merged_rds:
        print("Delete merged remote refs:")
        for d in sorted(merged_rds, key=lambda x:(x.remote,x.branch)):
            suffix = " (non-upstream)" if d.nonupstream else ""
            print(f"  - {d.remote}, refs/heads/{d.branch}{suffix}")
    if div_rds:
        print("Delete diverged remote refs:")
        for d in sorted(div_rds, key=lambda x:(x.remote,x.branch)):
            print(f"  - {d.remote}, refs/heads/{d.branch}")
    if stray_deletes:
        print("Delete stray local branches:")
        for d in sorted(stray_deletes, key=lambda x:x.name):
            print(f"  - {d.name}")

    all_local = sorted(stray_deletes, key=lambda x:x.name) + sorted(local_deletes, key=lambda x:x.name)
    any_deletes = bool(all_local or remote_deletes)
    if any_deletes and (not opts.dry_run) and (not opts.no_confirm):
        if not sys.stdin.isatty():
            eprint("Error: IO error: not a terminal")
            eprint()
            eprint("Caused by:")
            eprint("    not a terminal")
            return 1
        try:
            ans = input("Delete branches? [y/N] ")
        except Exception:
            return 1
        if ans.lower() not in ('y','yes'):
            return 0

    # Execute/dry-run remote deletions.  Group per remote and kind-independent, matching git's push output.
    by_remote: Dict[str, List[str]] = {}
    for d in remote_deletes:
        by_remote.setdefault(d.remote, []).append(d.branch)
    # The observed program tends to run non-upstream remotes before upstream deletion; sorting is adequate.
    for remote in sorted(by_remote):
        branches = sorted(set(by_remote[remote]))
        cmd = ['git','push']
        if opts.dry_run:
            cmd.append('--dry-run')
        cmd.append(remote)
        cmd += [f":refs/heads/{b}" for b in branches]
        subprocess.run(cmd, text=True)

    for d in all_local:
        if opts.dry_run:
            if current == d.name and not opts.no_detach:
                print(f"Note: switching to 'refs/heads/{d.name}' (dry run)")
                print("You are in 'detached HED' state... blah blah...")
                print(f"HEAD is now at {short_oid(d.oid)} {d.subject} (dry run)")
            print(f"Delete branch {d.name} (dry run).")
        else:
            if current == d.name and not opts.no_detach:
                subprocess.run(['git','checkout','--detach', f'refs/heads/{d.name}'], text=True)
                current = None
            subprocess.run(['git','branch','-D', d.name], text=True)
    return 0

def main() -> int:
    prog = os.path.basename(sys.argv[0]) or 'executable'
    parsed, code = parse_cli(sys.argv[1:], prog)
    if parsed is None:
        return code
    opts = parsed

    # Repository discovery through Git's normal interface.  Match the common outside-repo libgit2 message.
    p = run_git(['rev-parse', '--git-dir'])
    if p.returncode != 0:
        eprint("Error: could not find repository at '.'; class=Repository (6); code=NotFound (-3)")
        return 1

    opts, cfgerr = apply_config(opts)
    if cfgerr:
        eprint(f"Error: {cfgerr}")
        return 1

    delete_value = opts.delete if opts.delete is not None else 'merged:origin'
    try:
        spec = parse_delete_value(delete_value)
    except ValueError as ve:
        if opts.delete is not None and git_config('trim.delete') == opts.delete and opts.delete not in sys.argv:
            eprint(f"Error: {ve}")
            return 1
        # If it came from config but CLI omitted, same runtime style.
        cli_supplied = any(a == '--delete' or a.startswith('--delete=') or a == '-d' or a.startswith('-d') and a != '--dry-run' for a in sys.argv[1:])
        if not cli_supplied:
            eprint(f"Error: {ve}")
            return 1
        bad_item = str(ve).split('`')[1] if '`' in str(ve) else delete_value
        return invalid_value('--delete <DELETE>', bad_item, str(ve))

    patterns = split_csv(opts.protected)
    return render_and_act(opts, spec, patterns, opts.bases)

if __name__ == '__main__':
    sys.exit(main())
