#!/usr/bin/env python3
import sys, os, subprocess, fnmatch
from dataclasses import dataclass, field
from typing import Optional, List, Dict, Tuple, Set

LONG_ABOUT = "Automatically trims your tracking branches whose upstream branches are merged or stray.\n`git-trim` is a missing companion to the `git fetch --prune` and a proper, safer, faster alternative to your `<bash oneliner HERE>`."
SHORT_ABOUT = "Automatically trims your tracking branches whose upstream branches are merged or stray."
VERSION = "git-trim 0.4.4"

LONG_HELP_TAIL = """Usage: {prog} [OPTIONS]

Options:
